<?php require_once __DIR__.'/../admin_catalog.php';require __DIR__.'/../staff_header.php'; ?>
<section class="admin-catalog" aria-label="Danh sách nhân viên">
    <?php catalog_toolbar('Tìm nhân viên',count($users),'Nhập họ tên hoặc email nhân viên…','#employee-create'); ?>
    <div class="table-wrap catalog-table-scroll"><table class="catalog-table"><thead><tr><th>Nhân viên</th><th>Email đăng nhập</th><th>Vai trò</th><th>Trạng thái</th><th class="catalog-action-cell">Hành động</th></tr></thead><tbody>
    <?php foreach($users as $employee):$employeeId=(int)$employee['id'];$self=$employeeId===(int)$user['id']; ?>
        <tr data-catalog-row data-search="<?= e($employee['display_name'].' '.$employee['email']) ?>" data-status="<?= (int)$employee['active']?'active':'inactive' ?>" data-category="<?= e($employee['role']) ?>"><td><span class="catalog-name"><?= e($employee['display_name']) ?></span><span class="catalog-secondary">NV<?= str_pad((string)$employeeId,3,'0',STR_PAD_LEFT) ?><?= $self?' · Tài khoản của bạn':'' ?></span></td><td><?= e($employee['email']) ?></td><td><?= $employee['role']==='admin'?'Quản trị viên':'Staff / Lễ tân' ?></td><td><?php catalog_status((int)$employee['active']?'Hoạt động':'Đã khóa',(bool)$employee['active']); ?></td><td><div class="catalog-row-actions"><?php catalog_action('eye','Xem '.$employee['display_name'],'#employee-view-'.$employeeId);catalog_action('edit','Sửa '.$employee['display_name'],'#employee-edit-'.$employeeId);catalog_action((int)$employee['active']?'trash':'power',$self?'Không thể tự khóa tài khoản':((int)$employee['active']?'Khóa '.$employee['display_name']:'Mở khóa '.$employee['display_name']),'#employee-status-'.$employeeId,(bool)$employee['active'],$self); ?></div></td></tr>
    <?php endforeach;catalog_empty(5,(bool)$users); ?>
    </tbody></table></div>
    <p class="catalog-note">Biểu tượng thùng rác khóa quyền đăng nhập, giữ nguyên lịch sử thao tác. Không tự khóa/hạ quyền tài khoản đang dùng.</p>
    <?php foreach($users as $employee):$employeeId=(int)$employee['id'];$self=$employeeId===(int)$user['id'];$target=(int)$employee['active']?0:1; ?>
        <?php catalog_dialog_start('employee-view-'.$employeeId,$employee['display_name'],'Hồ sơ nhân viên');catalog_details(['Mã nhân viên'=>'NV'.str_pad((string)$employeeId,3,'0',STR_PAD_LEFT),'Họ tên'=>$employee['display_name'],'Email'=>$employee['email'],'Vai trò'=>$employee['role']==='admin'?'Quản trị viên':'Staff / Lễ tân','Trạng thái'=>(int)$employee['active']?'Hoạt động':'Đã khóa']); ?><div class="catalog-dialog-actions"><button type="button" class="button outline" data-close-dialog>Đóng</button></div><?php catalog_dialog_end(); ?>
        <?php $editingError=post()&&input('action')==='update'&&(int)input('id')===$employeeId&&$error!=='';catalog_dialog_start('employee-edit-'.$employeeId,'Chỉnh sửa nhân viên',$employee['display_name'],$editingError);if($editingError)catalog_error($error); ?>
        <form method="post"><?= csrf() ?><?php catalog_hidden(['action'=>'update','id'=>$employeeId]); ?><div class="form-grid"><label class="catalog-span">Họ tên<input name="display_name" value="<?= e($editingError?input('display_name'):$employee['display_name']) ?>" minlength="2" maxlength="100" required></label><label>Email đăng nhập<input type="email" name="email" value="<?= e($editingError?input('email'):$employee['email']) ?>" maxlength="190" required></label><label>Vai trò<?php if($self)catalog_hidden(['role'=>$employee['role']]); ?><select name="role" <?= $self?'disabled':'' ?>><option value="receptionist" <?= ($self?$employee['role']:($editingError?input('role'):$employee['role']))==='receptionist'?'selected':'' ?>>Staff / Lễ tân</option><option value="admin" <?= ($self?$employee['role']:($editingError?input('role'):$employee['role']))==='admin'?'selected':'' ?>>Quản trị viên</option></select></label><?php if(!$self): ?><label>Đặt lại mật khẩu<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" placeholder="Để trống nếu giữ mật khẩu cũ"></label><?php else: ?><p>Đổi mật khẩu của bạn tại <a class="text-link" href="<?= e(url('staff/account.php')) ?>">Tài khoản của tôi</a>.</p><?php endif; ?></div><?php if($self)catalog_hidden(['active'=>1]); ?><label class="checkbox"><input type="checkbox" name="active" value="1" <?= $self?'disabled':'' ?> <?= ($self||($editingError?input('active')==='1':(bool)$employee['active']))?'checked':'' ?>>Cho phép đăng nhập</label><?php catalog_form_actions('Lưu nhân viên'); ?></form><?php catalog_dialog_end(); ?>
        <?php if(!$self):catalog_dialog_start('employee-status-'.$employeeId,$target?'Mở khóa nhân viên':'Khóa nhân viên',$employee['display_name'],false,true); ?><p><?= $target?'Tài khoản sẽ được phép đăng nhập lại theo vai trò đang có.':'Tài khoản sẽ ngừng được đăng nhập; lịch sử nghiệp vụ và thao tác cũ vẫn được giữ.' ?></p><form method="post"><?= csrf() ?><?php catalog_hidden(['action'=>'update','id'=>$employeeId,'display_name'=>$employee['display_name'],'email'=>$employee['email'],'role'=>$employee['role'],'active'=>$target]);catalog_form_actions($target?'Mở khóa':'Khóa tài khoản',!$target); ?></form><?php catalog_dialog_end();endif; ?>
    <?php endforeach; ?>
    <?php $createError=post()&&input('action')==='create'&&$error!=='';catalog_dialog_start('employee-create','Thêm nhân viên','Tài khoản và vai trò đăng nhập',$createError);if($createError)catalog_error($error); ?>
    <form method="post"><?= csrf() ?><?php catalog_hidden(['action'=>'create']); ?><div class="form-grid"><label class="catalog-span">Họ tên<input name="display_name" value="<?= e($createError?input('display_name'):'') ?>" minlength="2" maxlength="100" required></label><label>Email đăng nhập<input type="email" name="email" value="<?= e($createError?input('email'):'') ?>" maxlength="190" autocomplete="off" required></label><label>Vai trò<select name="role"><option value="receptionist" <?= $createError&&input('role')==='receptionist'?'selected':'' ?>>Staff / Lễ tân</option><option value="admin" <?= $createError&&input('role')==='admin'?'selected':'' ?>>Quản trị viên</option></select></label><label>Mật khẩu ban đầu<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label></div><label class="checkbox"><input type="checkbox" name="active" value="1" <?= !$createError||input('active')==='1'?'checked':'' ?>>Cho phép đăng nhập</label><?php catalog_form_actions('Tạo nhân viên'); ?></form><?php catalog_dialog_end(); ?>
